//! Files two agents should not change at once even on different lines:
//! lockfiles, database migrations and generated files, which one command
//! rewrites whole.

use std::io::Read;
use std::path::Path;

use crate::server::edits::git;

const LOCKFILES: [&str; 18] = [
    "pnpm-lock.yaml",
    "package-lock.json",
    "npm-shrinkwrap.json",
    "yarn.lock",
    "bun.lock",
    "bun.lockb",
    "deno.lock",
    "Cargo.lock",
    "go.sum",
    "go.work.sum",
    "poetry.lock",
    "uv.lock",
    "Pipfile.lock",
    "pdm.lock",
    "Gemfile.lock",
    "composer.lock",
    "Podfile.lock",
    "Package.resolved",
];

const MIGRATION_FOLDERS: [&str; 2] = ["migrations", "migration"];
const GENERATED_FOLDERS: [&str; 2] = ["generated", "__generated__"];
const GENERATED_MARKS: [&str; 3] = ["@generated", "DO NOT EDIT", "Code generated by"];
/// How much of a file's start is read for a generated mark.
const HEAD_BYTES: u64 = 1024;

/// Why `path` is fragile, as a few words for a note, or none when it is not.
/// Generated files are found by name, by the repository's
/// `linguist-generated` attribute, or by the mark generators leave at the top.
pub(super) fn why(path: &Path) -> Option<&'static str> {
    let name = path.file_name()?.to_str()?;
    if LOCKFILES.contains(&name) {
        return Some("a lockfile");
    }
    let folders: Vec<&str> = path
        .parent()?
        .components()
        .filter_map(|part| part.as_os_str().to_str())
        .collect();
    if folders
        .iter()
        .any(|folder| MIGRATION_FOLDERS.contains(folder))
    {
        return Some("a migration");
    }
    let generated = name.contains(".generated.")
        || folders
            .iter()
            .any(|folder| GENERATED_FOLDERS.contains(folder))
        || marked_generated(path)
        || attributed_generated(path);
    generated.then_some("a generated file")
}

fn marked_generated(path: &Path) -> bool {
    let mut head = String::new();
    let read =
        std::fs::File::open(path).and_then(|file| file.take(HEAD_BYTES).read_to_string(&mut head));
    read.is_ok()
        && head
            .lines()
            .take(5)
            .any(|line| GENERATED_MARKS.iter().any(|mark| line.contains(mark)))
}

fn attributed_generated(path: &Path) -> bool {
    let (Some(dir), Some(name)) = (
        path.parent(),
        path.file_name().and_then(|name| name.to_str()),
    ) else {
        return false;
    };
    git(dir, &["check-attr", "linguist-generated", "--", name])
        .is_ok_and(|said| said.trim_end().ends_with(": set") || said.trim_end().ends_with(": true"))
}
